  final secrets = collectRoleSecrets(
    roles,
    keys,
    env: env,
    customProviders: saved.customProviders,
  );
  return ModelRolesResolver(
    config: roles,
    secrets: secrets,
    customProviders: saved.customProviders,
    streamFactory: _neverStream,
  );
}

