Future<ModelRolesResolver> _bootResolver(
  CliConfig saved,
  ModelRolesConfig roles, {
  Map<String, String> env = const {},
  Map<String, String> store = const {},
}) async {
  final fakeStore = FakeSecureKeyStore()..map.addAll(store);
